                for i := len(group.children) - 1; i >= 0; i-- {
                        switch v := group.children[i].(type) {
                        case *RouterGroup[T]:
                                v.Unbind(middlewareId)
                        case *Route[T]:
                                v.Unbind(middlewareId)
